-- Analytical View: Mutation by Histology---- Purpose:-- Provide sample-level mutation observations-- associated with the corresponding histological subtype.---- Grain:-- One row per sample and gene.---- Source:-- analytical.dim_sample-- analytical.fact_mutationCREATE OR REPLACE VIEW analytical.vw_mutation_by_histology ASSELECT    s.sample_id,    s.histological_type,    f.gene_name AS gene,    f.mutation_statusFROM analytical.dim_sample AS sINNER JOIN analytical.fact_mutation AS f    ON s.sample_id = f.sample_id;